// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts List accounts
	// (GET /api/v1/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Create an account
	// (POST /api/v1/accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// GetAccount Get an account
	// (GET /api/v1/accounts/{accountId})
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// UpdateAccount Rename an account or change its type
	// (PATCH /api/v1/accounts/{accountId})
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// AdjustAccountBalance Adjust the balance
	// (POST /api/v1/accounts/{accountId}/balance-adjustment)
	AdjustAccountBalance(ctx context.Context, request AdjustAccountBalanceRequestObject) (AdjustAccountBalanceResponseObject, error)
	// DeleteAccount Delete an account
	// (POST /api/v1/accounts/{accountId}/delete)
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// Login Log in
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Log out
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListBuckets List buckets
	// (GET /api/v1/buckets)
	ListBuckets(ctx context.Context, request ListBucketsRequestObject) (ListBucketsResponseObject, error)
	// CreateBucket Create a bucket
	// (POST /api/v1/buckets)
	CreateBucket(ctx context.Context, request CreateBucketRequestObject) (CreateBucketResponseObject, error)
	// DeleteBucket Delete a bucket
	// (DELETE /api/v1/buckets/{bucketId})
	DeleteBucket(ctx context.Context, request DeleteBucketRequestObject) (DeleteBucketResponseObject, error)
	// GetBucket Get a bucket
	// (GET /api/v1/buckets/{bucketId})
	GetBucket(ctx context.Context, request GetBucketRequestObject) (GetBucketResponseObject, error)
	// UpdateBucket Change a bucket's settings
	// (PATCH /api/v1/buckets/{bucketId})
	UpdateBucket(ctx context.Context, request UpdateBucketRequestObject) (UpdateBucketResponseObject, error)
	// ListCycles List cycles
	// (GET /api/v1/cycles)
	ListCycles(ctx context.Context, request ListCyclesRequestObject) (ListCyclesResponseObject, error)
	// CreateCycle Plan a cycle
	// (POST /api/v1/cycles)
	CreateCycle(ctx context.Context, request CreateCycleRequestObject) (CreateCycleResponseObject, error)
	// GetCurrentCycles The active and next cycle
	// (GET /api/v1/cycles/active)
	GetCurrentCycles(ctx context.Context, request GetCurrentCyclesRequestObject) (GetCurrentCyclesResponseObject, error)
	// DeleteCycle Delete a planned cycle
	// (DELETE /api/v1/cycles/{cycleId})
	DeleteCycle(ctx context.Context, request DeleteCycleRequestObject) (DeleteCycleResponseObject, error)
	// GetCycle Get a cycle
	// (GET /api/v1/cycles/{cycleId})
	GetCycle(ctx context.Context, request GetCycleRequestObject) (GetCycleResponseObject, error)
	// UpdateCycle Move or extend a cycle
	// (PATCH /api/v1/cycles/{cycleId})
	UpdateCycle(ctx context.Context, request UpdateCycleRequestObject) (UpdateCycleResponseObject, error)
	// EndCycle End the active cycle
	// (POST /api/v1/cycles/{cycleId}/end)
	EndCycle(ctx context.Context, request EndCycleRequestObject) (EndCycleResponseObject, error)
	// StartCycle Start a planned cycle
	// (POST /api/v1/cycles/{cycleId}/start)
	StartCycle(ctx context.Context, request StartCycleRequestObject) (StartCycleResponseObject, error)
	// GetMe The current user
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangePassword Change the password
	// (POST /api/v1/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// UpdatePreferences Update preferences
	// (PATCH /api/v1/me/preferences)
	UpdatePreferences(ctx context.Context, request UpdatePreferencesRequestObject) (UpdatePreferencesResponseObject, error)
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness probe
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

